"""Build settings of the comparison subset's projects, and the ones `gerbil execution` measures."""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum


class BuildTool(str, Enum):
    MAVEN = "maven"
    GRADLE = "gradle"


class Suite(str, Enum):
    DEVELOPER = "developer"
    CLAUDE_CODE = "claude-code"
    CODEX = "codex"
    # Generated by `gerbil evomaster run` rather than taken from a Gerbil analysis.
    EVOMASTER = "evomaster"


@dataclass(frozen=True)
class ExecutionProject:
    """A project's build settings; `jvm_args` mirror the project's own test JVM flags.

    `pit_threads` caps PIT's parallel workers for suites whose tests bind fixed
    ports or open an on-disk index, which concurrent workers would collide on.
    `pit_containers` splits a suite's mutated classes over that many PIT runs in
    containers of their own, each with its own copy of `pit_private_directories` (of
    the workspace), where the suite's JVMs would otherwise collide.
    `maven_phase` is the phase that builds the test classes, `workspace_copies` are
    (source, target) files that the project's own CI creates before building, and
    `workspace_restores` are test data paths the build requires that test clearing
    removed from agent suites; only the files a suite's tree lacks come back, so the
    suite's own edits there survive. `extra_build_modules` are Maven modules built
    alongside the test modules.
    """

    name: str
    dataset_name: str
    build_tool: BuildTool
    jdk: int
    build_root: str = "."
    build_args: tuple[str, ...] = ()
    jvm_args: tuple[str, ...] = ()
    pit_threads: int | None = None
    pit_containers: int = 1
    pit_private_directories: tuple[str, ...] = ()
    maven_phase: str = "test-compile"
    workspace_copies: tuple[tuple[str, str], ...] = ()
    workspace_restores: tuple[str, ...] = ()
    extra_build_modules: tuple[str, ...] = ()


_DSPACE_TEST_INSTALLATION = "/workspace/dspace-server-webapp/target/testing/dspace"

# PIT runs on Java 11+, so Java 8 projects (kylin, dolphinscheduler) run on JDK 11.
PROJECTS: dict[str, ExecutionProject] = {
    project.name: project
    for project in (
        ExecutionProject(
            "cbioportal",
            "cBioPortal_cbioportal",
            BuildTool.MAVEN,
            21,
            workspace_copies=(
                (
                    "src/main/resources/application.properties.EXAMPLE",
                    "src/main/resources/application.properties",
                ),
            ),
        ),
        ExecutionProject(
            "dolphinscheduler",
            "apache_dolphinscheduler",
            BuildTool.MAVEN,
            11,
            # One PIT run of the EvoMaster suite takes more than a day.
            pit_containers=6,
        ),
        ExecutionProject(
            "DSpace",
            "DSpace_DSpace",
            BuildTool.MAVEN,
            17,
            # Unpacks the test installation these tests load before test-compile; the
            # installation's assembly takes its configuration from the dspace module.
            build_args=("-DskipUnitTests=false",),
            extra_build_modules=("dspace",),
            # Every JVM opens the test installation's Solr cores under one directory
            # with native locks, so a second worker's cores fail to load: a container
            # runs one worker, on its own copy of the installation.
            pit_threads=1,
            pit_containers=6,
            pit_private_directories=("dspace-server-webapp/target/testing/dspace",),
            jvm_args=(
                f"-Ddspace.dir={_DSPACE_TEST_INSTALLATION}",
                f"-Dsolr.install.dir={_DSPACE_TEST_INSTALLATION}/solr/",
                "-Ddspace.log.init.disable=true",
            ),
            workspace_restores=(
                "dspace-api/src/test/data",
                "dspace-server-webapp/src/test/data",
            ),
        ),
        ExecutionProject(
            "hertzbeat",
            "apache_hertzbeat",
            BuildTool.MAVEN,
            17,
            jvm_args=(
                "--add-opens=java.base/java.nio=org.apache.arrow.memory.core,ALL-UNNAMED",
            ),
        ),
        ExecutionProject(
            "incubator-kie-kogito-runtimes",
            "apache_incubator-kie-kogito-runtimes",
            BuildTool.MAVEN,
            17,
            # 999-SNAPSHOT has moved past the pinned commit, so use the weekly build
            # from the same week. jbpm-bpmn2 unpacks a sibling module's jar during
            # its build.
            build_args=("-DskipTests", "-Dversion.org.kie=999-20250622-SNAPSHOT"),
            maven_phase="package",
            # Test clearing deletes these shared helper modules, which the reactor needs.
            workspace_restores=(
                "quarkus/addons/kubernetes/test-utils",
                "quarkus/test",
                "springboot/test",
            ),
        ),
        ExecutionProject(
            "kylin",
            "apache_kylin",
            BuildTool.MAVEN,
            11,
            # PowerMock reloads javax.xml classes outside java.xml, which Java 8 allowed.
            jvm_args=("--add-exports=java.xml/jdk.xml.internal=ALL-UNNAMED",),
            # One PIT run of the EvoMaster suite takes about a day, and one of the
            # developer suite's kylin-server-it module several hours; a JVM that finds
            # the metadata copy locked makes its own, so runs can share the workspace.
            pit_containers=6,
        ),
        ExecutionProject(
            "openvsx", "eclipse_openvsx", BuildTool.GRADLE, 17, build_root="server"
        ),
        ExecutionProject(
            "spinnaker", "spinnaker_spinnaker", BuildTool.GRADLE, 17, pit_threads=1
        ),
        ExecutionProject(
            "spring-cloud-dataflow",
            "spring-attic_spring-cloud-dataflow",
            BuildTool.MAVEN,
            17,
            # The profile declares the repository serving the deployer snapshots.
            build_args=("-Pspring",),
            # One PIT run of the EvoMaster suite takes more than a day.
            pit_containers=4,
        ),
        ExecutionProject(
            "uaa",
            "cloudfoundry_uaa",
            BuildTool.GRADLE,
            17,
            # Set only by the project's docsTestRestDocs task; every *Docs test needs it.
            jvm_args=("-Ddocs.build.generated.snippets.dir=build/generated-snippets",),
            # The developer suite's uaa module starts a web app per test, so one PIT
            # run of it takes more than half a day; the EvoMaster suite's PostgreSQL
            # lives in each container's temporary directory.
            pit_containers=6,
        ),
    )
}

# cbioportal has no 1-hour EvoMaster suite, so it is characterized statically only.
MEASURED_PROJECTS: dict[str, ExecutionProject] = {
    name: project for name, project in PROJECTS.items() if name != "cbioportal"
}
